// functions
// draw a circle
float circle(vec2 uv, vec2 center, float radius)
{
    return smoothstep(radius, radius - 0.0027, length(uv - center));
}

// get luminance value of a colour [0-1]
float luma(vec4 color)
{
    return dot(color.rgb, vec3(0.299, 0.587, 0.114));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    const float PARTITIONS_X = 40.0;
    const float PARTITIONS_Y = 40.0;


    // normalize pixels [0-1]
    vec2 uv = fragCoord/iResolution.xy;
    uv.x *= iResolution.x/iResolution.y;

    // pixel color (to look at something for now)
    //vec4 colT = vec4(luma(texture(iChannel0, vec2(0.4,0.4))));

    vec4 colF = vec4(1.0,1.0,1.0, 1.0);

    // loop through the texture and sample pixels accordingly
    // then draw luma circles and check how far we are....
    // this is much beter done with gaussian blur but i want to get 
    // circles working rn
    float partitionX = 1.0 / PARTITIONS_X;
    float partitionY = 1.0 / PARTITIONS_Y;
    float even = 0.0;

    for (float i = partitionX / 2.0; i < iResolution.x/iResolution.y; i += partitionX/2.0)
    {
        for (float j = (1.0 + float(mod(even, 2.0))) * partitionY / 2.0; j < 1.0; j += partitionY)
        {
            colF.bg -= circle(uv, vec2(i, j), (partitionX/1.6)*luma(texture(iChannel0, vec2(i,j))));
        }
        even+=1.0;
    }

    // output to screen
    fragColor = colF;
}
